import HowItWorksSectionV2 from "./how-it-works-section-v2"

export default function Page() {
  return <HowItWorksSectionV2 />
}

"use client"

import StepsGrid from "./components/steps-grid"
import "./styles/how-it-works-section-v2.css"

export default function HowItWorksSectionV2() {
  return (
    <section className="py-16 md:py-20 lg:py-24">
      <StepsGrid
        title={
          <h2
            className="text-4xl font-light tracking-tight leading-tight sm:text-5xl lg:text-6xl"
          >
            How It Works
          </h2>
        }
      />
    </section>
  )
}

"use client"

import type { ReactNode } from "react"
import { useRef } from "react"

import { Badge } from "@/components/ui/badge"

import { useHiw2V2Animations } from "../hooks/use-hiw2-v2-animations"
import { STEP_LABEL_BADGE_VARIANT, steps } from "../lib/steps"
import StepCard from "./step-card"

type StepsGridProps = {
  title: ReactNode
}

export default function StepsGrid({ title }: StepsGridProps) {
  const titleRef = useRef<HTMLDivElement>(null)
  const cardRefs = useRef<(HTMLDivElement | null)[]>([])
  const borderRefs = useRef<(HTMLDivElement | null)[]>([])

  useHiw2V2Animations({
    title: titleRef,
    cards: cardRefs,
    borders: borderRefs,
  })

  return (
    <div className="mx-auto max-w-6xl px-4">
      <div ref={titleRef} className="mb-12 md:mb-16">
        {title}
      </div>

      <div className="grid grid-cols-1 gap-10 md:grid-cols-3 md:gap-8 lg:gap-14">
        {steps.map((step, i) => (
          <div
            key={step.id}
            ref={(el) => {
              cardRefs.current[i] = el
            }}
          >
            <Badge
              variant={STEP_LABEL_BADGE_VARIANT}
              className="uppercase"
            >
              {step.label}
            </Badge>

            <div
              ref={(el) => {
                borderRefs.current[i] = el
              }}
              className="hiw2-card-border"
            />

            <StepCard step={step} />
          </div>
        ))}
      </div>
    </div>
  )
}

import { CheckCircle2 } from "lucide-react"

import type { Step } from "../lib/steps"

type Props = {
  step: Step
}

export default function StepCard({ step }: Props) {
  return (
    <div className="flex flex-col gap-4 pt-4">
      <h3 className="text-xl font-medium tracking-tight leading-snug text-foreground">
        {step.title}
      </h3>

      <ul className="flex flex-col gap-3">
        {step.features.map((feature, index) => (
          <li
            key={index}
            data-hiw2-feature=""
            className="flex items-start gap-3 text-sm text-muted-foreground leading-relaxed"
          >
            <CheckCircle2 className="hiw2-check-icon h-4 w-4 fill-foreground stroke-background" />
            <span>{feature}</span>
          </li>
        ))}
      </ul>
    </div>
  )
}

export const STEP_LABEL_BADGE_VARIANT = "outline" as const

export type StepFeature = string

export type Step = {
  id: string
  label: string
  title: string
  features: StepFeature[]
}

export const steps: Step[] = [
  {
    id: "step-1",
    label: "Step 1",
    title: "Create your project",
    features: [
      "Scaffold a new Next.js app with a single command",
      "Choose Tailwind CSS and App Router when prompted",
      "TypeScript support included out of the box",
    ],
  },
  {
    id: "step-2",
    label: "Step 2",
    title: "Initialize shadcn/ui",
    features: [
      "Run the shadcn CLI to configure your project",
      "Sets up components.json with your preferred style",
      "Adds the necessary Tailwind and import alias config",
    ],
  },
  {
    id: "step-3",
    label: "Step 3",
    title: "Add components",
    features: [
      "Install only the components you actually need",
      "Code is copied directly into your project",
      "Fully customizable — no black-box dependencies",
    ],
  },
]

.hiw2-check-icon {
  color: hsl(var(--foreground));
  flex-shrink: 0;
  margin-top: 2px;
}

.hiw2-card-border {
  height: 1px;
  background: hsl(var(--border));
  margin-bottom: 1rem;
}
